                      3. SO LUONG NO-RON CUA LAOP DAU RA, SLNRLR
Gia tri tra ve: TRUNG BINH BINH PHUONG SAI SO DAU RA CUA LOP RA
-----------------------------------------------------------------------
*/

float TB_BINHPHUONGSAISO(int a[],float b[],int SIZE)
{
    int i;
    float e=0;

    for(i=0;i<SIZE;i++)
        e = e + ((float)a[i] - b[i])*(a[i] - b[i]);
    e = 0.5 * e;
    return e;
}

